/// <reference no-default-lib="true"/>

// A replacement library in the shape of the roblox-ts types: `Array` extends
// `ReadonlyArray`, strings have Luau methods, and `math` is a namespace.

interface Boolean {}
interface CallableFunction {}
interface Function {}
interface IArguments {}
interface NewableFunction {}
interface Number {}
interface Object {}
interface RegExp {}

interface String {
	gsub(pattern: string, replacement: string | ((match: string) => string)): string;
	size(): number;
	upper(): string;
}

interface ReadonlyArray<T> {
	filterUndefined(): Array<T>;
	find(predicate: (value: T) => boolean): T | undefined;
	forEach(callback: (value: T) => void): void;
	isEmpty(): boolean;
	map<U>(callback: (value: T) => U): Array<U>;
	copyInto(target: MutableList<T>): MutableList<T>;
	move(f: number, e: number, t: number, a2: Array<T>): Array<T>;
	size(): number;
}

type MutableList<T> = Array<T>;

interface Array<T> extends ReadonlyArray<T> {
	push(...items: Array<T>): number;
}

declare namespace math {
	function abs(x: number): number;
	function randomseed(seed: number): void;
}

declare namespace table {
	function clone<T>(value: T): T;
	function freeze<T>(value: T): T;
}

declare namespace task {
	function spawn(callback: () => void): unknown;
	function wait(seconds?: number): number;
}

declare function typeIs(value: unknown, name: string): boolean;
declare function setmetatable<T>(value: T, meta: object): T;
